insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Polity','Parliament & State Legislature','statement_based','hard','Consider the following statements about committees of the Lok Sabha:','लोकसभा की समितियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Committee on Subordinate Legislation examines whether rules framed by the executive stay within the powers delegated by Parliament.", "The Committee on Government Assurances is chaired by the Minister of Parliamentary Affairs.", "The Speaker is the ex officio chairperson of the Rules Committee."], "statements_hi": ["अधीनस्थ विधान समिति यह जाँचती है कि कार्यपालिका द्वारा बनाए गए नियम संसद द्वारा सौंपी गई शक्तियों की सीमा में हैं या नहीं।", "सरकारी आश्वासन समिति की अध्यक्षता संसदीय कार्य मंत्री करते हैं।", "अध्यक्ष (स्पीकर) नियम समिति के पदेन सभापति होते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. The Committee on Subordinate Legislation scrutinises rules, regulations and bye-laws made under Acts to see that they do not go beyond, or against, what the parent law allows. The Rules Committee, which considers changes to the House''s procedure, is headed by the Speaker (in the Rajya Sabha, by the Chairman). Statement 2 is wrong: the Committee on Government Assurances checks whether promises made by ministers on the floor of the House have been kept. Its members are nominated by the Speaker and ministers are not among them -- a minister could hardly check the Government''s own promises.','कथन 1 और 3 सही हैं। अधीनस्थ विधान समिति अधिनियमों के तहत बने नियमों, विनियमों और उपविधियों की जाँच करती है कि वे मूल क़ानून की अनुमति से आगे या उसके विरुद्ध तो नहीं जाते। नियम समिति, जो सदन की प्रक्रिया में बदलावों पर विचार करती है, अध्यक्ष (राज्यसभा में सभापति) की अध्यक्षता में होती है। कथन 2 गलत है: सरकारी आश्वासन समिति यह देखती है कि मंत्रियों ने सदन में जो वादे किए वे पूरे हुए या नहीं। इसके सदस्य अध्यक्ष द्वारा मनोनीत होते हैं और मंत्री इसमें शामिल नहीं होते, क्योंकि कोई मंत्री स्वयं सरकार के वादों की जाँच नहीं कर सकता।','parl-committees-subleg-assurances-rules','original_pattern_matched','Rules of Procedure and Conduct of Business in Lok Sabha -- parliamentary committees; Lok Sabha Secretariat -- Practice and Procedure of Parliament.','draft'),
('upsc','Polity','Parliament & State Legislature','statement_based','medium','Consider the following statements about the party whip in Parliament:','संसद में दलीय सचेतक (व्हिप) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The office of whip is not mentioned in the Constitution of India.", "A member who votes against the party''s direction may be disqualified, unless the party condones it within fifteen days."], "statements_hi": ["सचेतक (व्हिप) के पद का उल्लेख भारत के संविधान में नहीं है।", "दल के निर्देश के विरुद्ध मतदान करने वाला सदस्य अयोग्य ठहराया जा सकता है, जब तक कि दल पंद्रह दिनों के भीतर उसे माफ़ न कर दे।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. The whip -- the party office-bearer who keeps members present and voting as the party decides -- rests on parliamentary convention, not on any Article of the Constitution. Under paragraph 2(1)(b) of the Tenth Schedule, voting or abstaining against the party''s direction without its prior permission is a ground for disqualification, but not if the party condones the act within fifteen days. The Presiding Officer decides such petitions.','दोनों कथन सही हैं। सचेतक, यानी दल का वह पदाधिकारी जो सदस्यों की उपस्थिति और दल के निर्णय के अनुसार मतदान सुनिश्चित करता है, संसदीय परंपरा पर आधारित है, संविधान के किसी अनुच्छेद पर नहीं। दसवीं अनुसूची के अनुच्छेद 2(1)(ख) के तहत दल की पूर्व अनुमति के बिना उसके निर्देश के विरुद्ध मतदान करना या मतदान से अलग रहना अयोग्यता का आधार है, पर तब नहीं जब दल पंद्रह दिनों के भीतर उस कार्य को माफ़ कर दे। ऐसी याचिकाओं पर पीठासीन अधिकारी निर्णय करते हैं।','parl-whip-tenth-schedule-condonation','original_pattern_matched','Constitution of India -- Tenth Schedule, paragraph 2; Lok Sabha Secretariat -- Practice and Procedure of Parliament.','draft'),
('upsc','Polity','Parliament & State Legislature','statement_based','medium','Consider the following statements about the Consultative Committees attached to Union ministries:','केंद्रीय मंत्रालयों से जुड़ी परामर्शदात्री समितियों (Consultative Committees) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["They are constituted by the Ministry of Parliamentary Affairs.", "They are chaired by the Speaker of the Lok Sabha.", "Every Member of Parliament is required to serve on at least one of them."], "statements_hi": ["इनका गठन संसदीय कार्य मंत्रालय करता है।", "इनकी अध्यक्षता लोकसभा अध्यक्ष करते हैं।", "प्रत्येक संसद सदस्य के लिए इनमें से कम से कम एक समिति में रहना अनिवार्य है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. The Ministry of Parliamentary Affairs constitutes these committees, which give members of both Houses an informal forum to discuss a ministry''s policies and programmes with its minister. Statement 2 is wrong: the minister in charge of the ministry chairs its Consultative Committee. Statement 3 is wrong: membership is voluntary and left to the choice of members and the leaders of their parties. The committees are not parliamentary committees in the strict sense, and they meet both during and between sessions.','केवल कथन 1 सही है। संसदीय कार्य मंत्रालय इन समितियों का गठन करता है, जो दोनों सदनों के सदस्यों को किसी मंत्रालय की नीतियों और कार्यक्रमों पर उसके मंत्री से अनौपचारिक चर्चा का मंच देती हैं। कथन 2 गलत है: संबंधित मंत्रालय का प्रभारी मंत्री उसकी परामर्शदात्री समिति की अध्यक्षता करता है। कथन 3 गलत है: सदस्यता स्वैच्छिक है और सदस्यों तथा उनके दलों के नेताओं की पसंद पर छोड़ी जाती है। ये समितियाँ कड़े अर्थ में संसदीय समितियाँ नहीं हैं, और सत्र के दौरान तथा दो सत्रों के बीच, दोनों समय बैठती हैं।','parl-consultative-committees-mopa','original_pattern_matched','Ministry of Parliamentary Affairs -- Consultative Committees of Members of Parliament; Lok Sabha Secretariat -- Practice and Procedure of Parliament.','draft'),
('upsc','Polity','Union & State Executive','mcq','hard','With reference to the office of the Deputy Prime Minister of India, which one of the following statements is correct?','भारत के उप-प्रधानमंत्री के पद के संदर्भ में निम्नलिखित में से कौन-सा कथन सही है?','{}'::jsonb,'[{"id": "a", "body": "Its holder automatically becomes Prime Minister if that office falls vacant, until the next general election.", "body_hi": "प्रधानमंत्री का पद रिक्त होने पर इसका धारक अगले आम चुनाव तक अपने आप प्रधानमंत्री बन जाता है।", "isCorrect": false}, {"id": "b", "body": "It was created by the 44th Amendment, which also fixed the term of its holder at five years.", "body_hi": "इसे 44वें संशोधन ने बनाया, जिसने इसके धारक का कार्यकाल भी पाँच वर्ष तय किया।", "isCorrect": false}, {"id": "c", "body": "It is not mentioned in the Constitution, and in law its holder is only a Union minister.", "body_hi": "संविधान में इसका उल्लेख नहीं है, और क़ानूनन इसका धारक केवल एक केंद्रीय मंत्री है।", "isCorrect": true}, {"id": "d", "body": "Its holder takes a separate oath, set out in the Third Schedule, as Deputy Prime Minister.", "body_hi": "इसका धारक तीसरी अनुसूची में दी गई उप-प्रधानमंत्री की एक अलग शपथ लेता है।", "isCorrect": false}]'::jsonb,2,0.66,'The Constitution provides for a Prime Minister and a Council of Ministers but not for a Deputy Prime Minister; the title is a political choice, held for example by Sardar Patel, Morarji Desai and L.K. Advani. In K.M. Sharma v. Devi Lal (1990) the Supreme Court upheld Devi Lal''s oath as ''Deputy Prime Minister'' because in substance he had taken the oath of a Union minister; the description gave him no extra power. The office carries no right of succession -- if the Prime Minister''s office falls vacant, the President appoints a new Prime Minister -- and the Third Schedule has no separate oath for it.','संविधान प्रधानमंत्री और मंत्रिपरिषद का प्रावधान करता है, उप-प्रधानमंत्री का नहीं; यह पदनाम एक राजनीतिक निर्णय है, जो उदाहरण के लिए सरदार पटेल, मोरारजी देसाई और लालकृष्ण आडवाणी के पास रहा। के.एम. शर्मा बनाम देवी लाल (1990) में सर्वोच्च न्यायालय ने ''उप-प्रधानमंत्री'' के रूप में देवी लाल की शपथ को वैध माना, क्योंकि सार रूप में उन्होंने केंद्रीय मंत्री की ही शपथ ली थी; इस पदनाम से उन्हें कोई अतिरिक्त शक्ति नहीं मिली। इस पद के साथ उत्तराधिकार का कोई अधिकार नहीं है; प्रधानमंत्री का पद रिक्त होने पर राष्ट्रपति नया प्रधानमंत्री नियुक्त करते हैं, और तीसरी अनुसूची में इसके लिए कोई अलग शपथ नहीं है।','exec-deputy-pm-devi-lal','original_pattern_matched','Supreme Court of India -- K.M. Sharma v. Devi Lal (1990); Constitution of India, Articles 74-75 and the Third Schedule.','draft'),
('upsc','Polity','Constitutional Framework','statement_based','hard','Consider the following statements about privy purses:','प्रिवी पर्स (privy purse) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Article 291 of the original Constitution guaranteed privy purses to the rulers of the former princely states.", "The Constitution (Twenty-sixth Amendment) Act, 1971 abolished privy purses and ended the recognition of the rulers.", "In the Madhav Rao Scindia case (1970), the Supreme Court upheld the President''s order derecognising the rulers."], "statements_hi": ["मूल संविधान का अनुच्छेद 291 पूर्व रियासतों के शासकों को प्रिवी पर्स की गारंटी देता था।", "संविधान (छब्बीसवाँ संशोधन) अधिनियम, 1971 ने प्रिवी पर्स समाप्त किए और शासकों की मान्यता ख़त्म की।", "माधवराव सिंधिया मामले (1970) में सर्वोच्च न्यायालय ने शासकों की मान्यता समाप्त करने वाले राष्ट्रपति के आदेश को वैध ठहराया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Rulers who acceded to India were promised tax-free yearly payments charged on the Consolidated Fund of India under Article 291, along with personal privileges under Article 362. When a Bill to end them fell short in the Rajya Sabha in 1970, the President issued an order derecognising all the rulers. Statement 3 is wrong: in Madhav Rao Scindia v. Union of India (1970) the Supreme Court struck that order down. Parliament then passed the 26th Amendment (1971), which omitted Articles 291 and 362 and inserted Article 363A.','कथन 1 और 2 सही हैं। भारत में विलय करने वाले शासकों को अनुच्छेद 291 के तहत भारत की संचित निधि पर भारित कर-मुक्त वार्षिक भुगतान और अनुच्छेद 362 के तहत व्यक्तिगत विशेषाधिकारों का वचन दिया गया था। 1970 में इन्हें समाप्त करने वाला विधेयक राज्यसभा में पारित नहीं हो सका, तो राष्ट्रपति ने सभी शासकों की मान्यता समाप्त करने का आदेश जारी किया। कथन 3 गलत है: माधवराव सिंधिया बनाम भारत संघ (1970) में सर्वोच्च न्यायालय ने वह आदेश रद्द कर दिया। इसके बाद संसद ने 26वाँ संशोधन (1971) पारित किया, जिसने अनुच्छेद 291 और 362 हटाए और अनुच्छेद 363A जोड़ा।','cf-privy-purses-26th-amendment','original_pattern_matched','Constitution of India -- Articles 291, 362 and 363A; Supreme Court of India -- Madhav Rao Scindia v. Union of India (1970).','draft'),
('upsc','Polity','Constitutional Framework','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "All provisions of the Constitution of India came into force on 26 January 1950.", "assertion_hi": "भारत के संविधान के सभी प्रावधान 26 जनवरी 1950 को लागू हुए।", "reason": "Article 394 lists the provisions that came into force on 26 November 1949, the day the Constitution was adopted.", "reason_hi": "अनुच्छेद 394 उन प्रावधानों को गिनाता है जो 26 नवंबर 1949 को, यानी संविधान अंगीकार किए जाने के दिन ही, लागू हो गए।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": true}]'::jsonb,2,0.66,'Statement-I is incorrect but Statement-II is correct. Article 394 brought some provisions into force at once on 26 November 1949: those on citizenship (Articles 5-9), the oath of the President (Article 60), elections (Article 324), definitions and interpretation, the provisional Parliament and other transitional provisions, and the short title and commencement themselves. The rest of the Constitution came into force on 26 January 1950, a date chosen to mark the anniversary of the Purna Swaraj pledge of 1930.','कथन-I गलत है पर कथन-II सही है। अनुच्छेद 394 ने कुछ प्रावधान 26 नवंबर 1949 को ही लागू कर दिए: नागरिकता (अनुच्छेद 5-9), राष्ट्रपति की शपथ (अनुच्छेद 60), चुनाव (अनुच्छेद 324), परिभाषाएँ और निर्वचन, अंतरिम संसद तथा अन्य संक्रमणकालीन प्रावधान, और स्वयं संक्षिप्त नाम तथा प्रारंभ से जुड़े प्रावधान। संविधान का शेष भाग 26 जनवरी 1950 को लागू हुआ; यह तिथि 1930 की पूर्ण स्वराज प्रतिज्ञा की वर्षगाँठ के रूप में चुनी गई।','cf-art394-commencement','original_pattern_matched','Constitution of India -- Article 394; NCERT Class XI, Political Science -- Indian Constitution at Work.','draft'),
('upsc','Polity','Federalism & Special Provisions','statement_based','medium','Consider the following statements about taxation between the Union and the States:','संघ और राज्यों के बीच कराधान के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Property of the Union is exempt from all taxes imposed by a State, unless Parliament by law provides otherwise.", "Income that a State earns from a trade or business is always exempt from Union taxes.", "The Constitution provides for fixed annual payments from Kerala and Tamil Nadu to certain Devaswom Funds."], "statements_hi": ["संघ की संपत्ति राज्य द्वारा लगाए गए सभी करों से मुक्त है, जब तक संसद क़ानून द्वारा अन्यथा प्रावधान न करे।", "किसी राज्य को व्यापार या कारोबार से होने वाली आय हर स्थिति में संघ के करों से मुक्त है।", "संविधान केरल और तमिलनाडु की ओर से कुछ देवस्वम निधियों को निश्चित वार्षिक भुगतान का प्रावधान करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. Article 285 shields Union property from State taxes, though local taxes already levied on such property before 1950 could continue until Parliament decided otherwise. Article 290A, inserted by the Seventh Amendment (1956), charges yearly sums on the Consolidated Funds of Kerala and Tamil Nadu for the Travancore Devaswom Fund and for the upkeep of Hindu temples in the areas transferred from Travancore-Cochin. Statement 2 is wrong: Article 289 exempts a State''s property and income from Union taxation, but clause (2) lets Parliament tax a trade or business carried on by or on behalf of a State, unless Parliament declares it incidental to the ordinary functions of government.','कथन 1 और 3 सही हैं। अनुच्छेद 285 संघ की संपत्ति को राज्य के करों से बचाता है, यद्यपि 1950 से पहले ऐसी संपत्ति पर लगे स्थानीय कर संसद के अन्यथा तय करने तक जारी रह सकते थे। सातवें संशोधन (1956) द्वारा जोड़ा गया अनुच्छेद 290A केरल और तमिलनाडु की संचित निधियों पर त्रावणकोर देवस्वम निधि के लिए तथा त्रावणकोर-कोचीन से हस्तांतरित क्षेत्रों के हिंदू मंदिरों के रख-रखाव के लिए वार्षिक राशि भारित करता है। कथन 2 गलत है: अनुच्छेद 289 राज्य की संपत्ति और आय को संघ के कराधान से मुक्त रखता है, पर उसका खंड (2) संसद को राज्य द्वारा या उसकी ओर से चलाए गए व्यापार या कारोबार पर कर लगाने देता है, जब तक संसद उसे सरकार के सामान्य कार्यों का आनुषंगिक घोषित न कर दे।','fed-art285-289-290a','original_pattern_matched','Constitution of India -- Articles 285, 289 and 290A.','draft'),
('upsc','Polity','Federalism & Special Provisions','statement_based','hard','Consider the following statements about the transfer of executive functions between the Union and the States:','संघ और राज्यों के बीच कार्यपालिका कार्यों के हस्तांतरण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The President may, with the consent of a State government, entrust to it functions that fall within the executive power of the Union.", "The Governor of a State may, with the consent of the Union government, entrust State functions to the Union or its officers.", "A law made by Parliament on a Union subject may confer powers and impose duties on a State''s officers even without the State''s consent."], "statements_hi": ["राष्ट्रपति किसी राज्य सरकार की सहमति से संघ की कार्यपालिका शक्ति के अंतर्गत आने वाले कार्य उसे सौंप सकते हैं।", "किसी राज्य के राज्यपाल संघ सरकार की सहमति से राज्य के कार्य संघ या उसके अधिकारियों को सौंप सकते हैं।", "संघ सूची के विषय पर संसद का बनाया क़ानून राज्य की सहमति के बिना भी राज्य के अधिकारियों को शक्तियाँ दे सकता है और उन पर कर्तव्य डाल सकता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three are correct. Article 258(1) allows the President to entrust Union functions to a State with its consent, and Article 258A, inserted by the Seventh Amendment (1956), allows the reverse with the Union''s consent. Under Article 258(2), a parliamentary law on a matter in the Union List may confer powers on a State or its officers whether or not the State agrees; the Union then pays the State the extra costs of administration, as agreed or as fixed by an arbitrator appointed by the Chief Justice of India (Article 258(3)). This two-way arrangement is one of the features that make Indian federalism co-operative rather than rigidly divided.','तीनों कथन सही हैं। अनुच्छेद 258(1) राष्ट्रपति को राज्य की सहमति से संघ के कार्य उसे सौंपने देता है, और सातवें संशोधन (1956) द्वारा जोड़ा गया अनुच्छेद 258A संघ की सहमति से इसका उल्टा करने देता है। अनुच्छेद 258(2) के तहत संघ सूची के विषय पर संसद का क़ानून राज्य या उसके अधिकारियों को शक्तियाँ दे सकता है, चाहे राज्य सहमत हो या नहीं; तब संघ प्रशासन का अतिरिक्त ख़र्च राज्य को चुकाता है, जो आपसी सहमति से या भारत के मुख्य न्यायाधीश द्वारा नियुक्त मध्यस्थ द्वारा तय होता है (अनुच्छेद 258(3))। यह दोतरफ़ा व्यवस्था उन विशेषताओं में से है जो भारतीय संघवाद को कठोर बँटवारे के बजाय सहकारी बनाती हैं।','fed-art258-258a-entrustment','original_pattern_matched','Constitution of India -- Articles 258 and 258A; NCERT Class XI, Political Science -- Indian Constitution at Work.','draft'),
('upsc','Polity','Panchayati Raj & Local Governance','match_the_following','medium','Consider the following pairs of urban bodies and their features:','नगरीय निकायों और उनकी विशेषताओं के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Cantonment board", "2. Notified area committee", "3. Township", "4. Special purpose agency"], "list_1_hi": ["1. छावनी बोर्ड", "2. अधिसूचित क्षेत्र समिति", "3. टाउनशिप", "4. विशेष प्रयोजन अभिकरण"], "list_2": ["Works under the Ministry of Defence", "Members elected under a notification of the State Election Commission", "Set up by a large public enterprise to run its staff colony", "Runs all the municipal functions of a large city"], "list_2_hi": ["रक्षा मंत्रालय के अधीन कार्य करता है", "राज्य निर्वाचन आयोग की अधिसूचना के तहत निर्वाचित सदस्य", "किसी बड़े सार्वजनिक उपक्रम द्वारा अपनी कर्मचारी बस्ती चलाने के लिए स्थापित", "किसी बड़े नगर के सभी नगरपालिका कार्य चलाता है"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Only the first and third pairs are correct. Cantonment boards, under the Cantonments Act, 2006, govern the civil population of military stations; they have elected as well as ex officio and nominated members and work under the Ministry of Defence. A notified area committee is set up by a State government notification for a new or fast-growing town that does not yet meet the conditions for a municipality; all its members, including the chairperson, are nominated by the State government. A township is run by a town administrator appointed by the enterprise that built it, with no elected members. Special purpose agencies, such as housing boards or water supply boards, handle one designated function, not the whole range of municipal work.','केवल पहला और तीसरा युग्म सही है। छावनी अधिनियम, 2006 के तहत छावनी बोर्ड सैन्य स्टेशनों की नागरिक आबादी का प्रशासन करते हैं; इनमें निर्वाचित के साथ पदेन और मनोनीत सदस्य होते हैं और ये रक्षा मंत्रालय के अधीन काम करते हैं। अधिसूचित क्षेत्र समिति राज्य सरकार की अधिसूचना से किसी नए या तेज़ी से बढ़ते क़स्बे के लिए बनाई जाती है जो अभी नगरपालिका की शर्तें पूरी नहीं करता; इसके अध्यक्ष सहित सभी सदस्य राज्य सरकार द्वारा मनोनीत होते हैं। टाउनशिप उसे बसाने वाले उपक्रम द्वारा नियुक्त नगर प्रशासक चलाता है और इसमें कोई निर्वाचित सदस्य नहीं होता। आवास बोर्ड या जल आपूर्ति बोर्ड जैसे विशेष प्रयोजन अभिकरण एक निर्धारित कार्य सँभालते हैं, नगरपालिका के सभी कार्य नहीं।','ulb-types-cantonment-notified-township-spa','original_pattern_matched','Cantonments Act, 2006; NCERT Class XI, Political Science -- Indian Constitution at Work -- Local Governments.','draft'),
('upsc','Polity','Judicial-Verdicts','statement_based','medium','Consider the following statements about the Constitution Bench judgment in Kaushal Kishor v. State of Uttar Pradesh (2023):','कौशल किशोर बनाम उत्तर प्रदेश राज्य (2023) में संविधान पीठ के निर्णय के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The grounds for restricting free speech listed in Article 19(2) are exhaustive, and no further restrictions can be added on other grounds.", "A statement made by a minister cannot be attributed vicariously to the Government, even if it relates to the Government''s affairs.", "The rights under Articles 19 and 21 can be enforced even against persons other than the State."], "statements_hi": ["अनुच्छेद 19(2) में दिए गए अभिव्यक्ति की स्वतंत्रता पर प्रतिबंध के आधार संपूर्ण हैं, और किसी अन्य आधार पर नए प्रतिबंध नहीं जोड़े जा सकते।", "किसी मंत्री के बयान को सरकार पर प्रतिनिधिक रूप से (vicariously) आरोपित नहीं किया जा सकता, भले ही वह सरकार के कामकाज से जुड़ा हो।", "अनुच्छेद 19 और 21 के अधिकार राज्य के अलावा अन्य व्यक्तियों के विरुद्ध भी लागू कराए जा सकते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three reflect the majority view (4:1). The case arose from a Uttar Pradesh minister''s remarks about a gang-rape case, and the question was whether ministers'' speech could be curbed beyond Article 19(2). The majority held that the grounds in Article 19(2) are exhaustive; that a minister''s statement, even if traceable to a matter of the State, cannot be attributed to the Government by invoking collective responsibility; and that Articles 19 and 21 can be enforced against non-State actors too. Justice B.V. Nagarathna, writing separately, differed on attributing ministers'' official statements and suggested that parties and Parliament frame codes to restrain disparaging speech by public functionaries.','तीनों कथन बहुमत के मत (4:1) को दर्शाते हैं। यह मामला उत्तर प्रदेश के एक मंत्री की एक सामूहिक बलात्कार मामले पर टिप्पणी से उठा, और प्रश्न यह था कि क्या मंत्रियों की अभिव्यक्ति पर अनुच्छेद 19(2) से आगे प्रतिबंध लग सकता है। बहुमत ने कहा कि अनुच्छेद 19(2) के आधार संपूर्ण हैं; कि मंत्री का बयान, भले ही राज्य के किसी मामले से जुड़ा हो, सामूहिक उत्तरदायित्व के नाम पर सरकार पर नहीं डाला जा सकता; और कि अनुच्छेद 19 और 21 ग़ैर-राज्य व्यक्तियों के विरुद्ध भी लागू हो सकते हैं। न्यायमूर्ति बी.वी. नागरत्ना ने अलग मत में मंत्रियों के आधिकारिक बयानों को सरकार पर आरोपित करने के प्रश्न पर असहमति जताई और सुझाव दिया कि दल और संसद सार्वजनिक पदाधिकारियों के अपमानजनक बयानों पर रोक के लिए आचार संहिता बनाएँ।','verdicts-kaushal-kishor-2023','original_pattern_matched','Supreme Court of India -- Kaushal Kishor v. State of Uttar Pradesh (2023).','draft'),
('upsc','Polity','Fundamental Rights, DPSP & Duties','statement_based','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Parliament may, by law, restrict or abrogate the Fundamental Rights of members of the armed forces and police forces to ensure discipline.", "Article 34 empowers the President to declare martial law in any part of the country.", "In Anuradha Bhasin v. Union of India (2020), the Supreme Court declared access to the internet a fundamental right in itself under Article 21."], "statements_hi": ["संसद क़ानून द्वारा अनुशासन बनाए रखने के लिए सशस्त्र बलों और पुलिस बलों के सदस्यों के मौलिक अधिकारों को सीमित या समाप्त कर सकती है।", "अनुच्छेद 34 राष्ट्रपति को देश के किसी भी भाग में सैन्य क़ानून (मार्शल लॉ) घोषित करने की शक्ति देता है।", "अनुराधा भसीन बनाम भारत संघ (2020) में सर्वोच्च न्यायालय ने इंटरनेट तक पहुँच को अनुच्छेद 21 के तहत अपने आप में एक मौलिक अधिकार घोषित किया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Article 33 lets Parliament -- not the State legislatures -- modify the rights of the armed forces, forces charged with public order, intelligence bodies and their communication services. Statement 2 is wrong: the Constitution nowhere says who may declare martial law; Article 34 only lets Parliament indemnify officers for acts done to restore order in an area where martial law was in force. Statement 3 is wrong: in Anuradha Bhasin the Court held that freedom of speech and the freedom to carry on trade over the internet are protected under Article 19(1)(a) and (g), so any shutdown must be necessary, proportionate, temporary and open to review; it did not declare internet access itself a separate fundamental right.','केवल कथन 1 सही है। अनुच्छेद 33 संसद को, न कि राज्य विधानमंडलों को, सशस्त्र बलों, लोक व्यवस्था के लिए उत्तरदायी बलों, ख़ुफ़िया संस्थाओं और उनकी संचार सेवाओं के अधिकारों में बदलाव की शक्ति देता है। कथन 2 गलत है: संविधान कहीं नहीं बताता कि मार्शल लॉ कौन घोषित करेगा; अनुच्छेद 34 केवल संसद को यह शक्ति देता है कि मार्शल लॉ वाले क्षेत्र में व्यवस्था बहाल करने के लिए किए गए कार्यों के लिए अधिकारियों को क्षतिपूर्ति (indemnity) दे। कथन 3 गलत है: अनुराधा भसीन मामले में न्यायालय ने कहा कि इंटरनेट के माध्यम से अभिव्यक्ति की स्वतंत्रता और व्यापार की स्वतंत्रता अनुच्छेद 19(1)(क) और (छ) के तहत संरक्षित हैं, इसलिए कोई भी इंटरनेट बंदी आवश्यक, आनुपातिक, अस्थायी और समीक्षा योग्य होनी चाहिए; इसने इंटरनेट तक पहुँच को अपने आप में अलग मौलिक अधिकार घोषित नहीं किया।','rights-art33-34-bhasin','original_pattern_matched','Constitution of India -- Articles 33 and 34; Supreme Court of India -- Anuradha Bhasin v. Union of India (2020).','draft'),
('upsc','Polity','Governance','mcq','medium','''Jeevan Pramaan'', a digital public service of the Government of India, is used for','भारत सरकार की डिजिटल सार्वजनिक सेवा ''जीवन प्रमाण'' का उपयोग किसके लिए होता है?','{}'::jsonb,'[{"id": "a", "body": "Digital life certificates for pensioners", "body_hi": "पेंशनभोगियों के डिजिटल जीवन प्रमाण-पत्र", "isCorrect": true}, {"id": "b", "body": "Telemedicine consultations with doctors", "body_hi": "डॉक्टरों से टेलीमेडिसिन परामर्श", "isCorrect": false}, {"id": "c", "body": "Single-window green clearances for projects", "body_hi": "परियोजनाओं के लिए एकल-खिड़की पर्यावरणीय मंज़ूरी", "isCorrect": false}, {"id": "d", "body": "Free online courses from school to postgraduate level", "body_hi": "स्कूल से स्नातकोत्तर स्तर तक निःशुल्क ऑनलाइन पाठ्यक्रम", "isCorrect": false}]'::jsonb,2,0.66,'Jeevan Pramaan (2014) lets pensioners submit their annual life certificate through Aadhaar-based fingerprint or face authentication, instead of appearing in person at a bank or office. Telemedicine is offered through e-Sanjeevani, environmental, forest and wildlife clearances through PARIVESH, and free online courses through SWAYAM.','जीवन प्रमाण (2014) पेंशनभोगियों को बैंक या कार्यालय में स्वयं उपस्थित होने के बजाय आधार-आधारित फ़िंगरप्रिंट या चेहरा प्रमाणीकरण से वार्षिक जीवन प्रमाण-पत्र जमा करने देता है। टेलीमेडिसिन ई-संजीवनी के माध्यम से, पर्यावरण, वन और वन्यजीव मंज़ूरी परिवेश (PARIVESH) के माध्यम से, और निःशुल्क ऑनलाइन पाठ्यक्रम स्वयं (SWAYAM) के माध्यम से मिलते हैं।','gov-jeevan-pramaan-digital-services','original_pattern_matched','Department of Pension and Pensioners'' Welfare -- Jeevan Pramaan; Ministry of Electronics and Information Technology.','draft'),
('upsc','Polity','Governance','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The first phase of the Vibrant Villages Programme covers villages along India''s northern land border.", "PM-JANMAN covers all Scheduled Tribes equally, without singling out any particular group."], "statements_hi": ["वाइब्रेंट विलेजेज़ कार्यक्रम का पहला चरण भारत की उत्तरी स्थल सीमा के गाँवों को शामिल करता है।", "पीएम-जनमन सभी अनुसूचित जनजातियों को समान रूप से शामिल करता है, किसी विशेष समूह को अलग से नहीं चुनता।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. The Vibrant Villages Programme (2023) develops thinly populated border villages in Arunachal Pradesh, Sikkim, Uttarakhand, Himachal Pradesh and Ladakh to improve livelihoods and slow outmigration; a second phase (2025) extends it to villages along other land borders. PM-JANMAN (2023) is aimed specifically at the 75 Particularly Vulnerable Tribal Groups (PVTGs), bringing their habitations housing, roads, piped water, electricity, health and education facilities.','केवल कथन 1 सही है। वाइब्रेंट विलेजेज़ कार्यक्रम (2023) अरुणाचल प्रदेश, सिक्किम, उत्तराखंड, हिमाचल प्रदेश और लद्दाख के कम आबादी वाले सीमावर्ती गाँवों का विकास करता है ताकि आजीविका सुधरे और पलायन रुके; इसका दूसरा चरण (2025) अन्य स्थल सीमाओं के गाँवों तक इसका विस्तार करता है। पीएम-जनमन (2023) विशेष रूप से 75 विशेष रूप से कमज़ोर जनजातीय समूहों (PVTGs) के लिए है, जिनकी बस्तियों तक आवास, सड़क, नल का जल, बिजली, स्वास्थ्य और शिक्षा की सुविधाएँ पहुँचाई जाती हैं।','gov-vibrant-villages-pm-janman','original_pattern_matched','Ministry of Home Affairs -- Vibrant Villages Programme; Ministry of Tribal Affairs -- PM-JANMAN.','draft'),
('upsc','Polity','Statutory-Laws','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "The Anusandhan National Research Foundation Act, 2023 repealed the Science and Engineering Research Board Act, 2008.", "assertion_hi": "अनुसंधान नेशनल रिसर्च फ़ाउंडेशन अधिनियम, 2023 ने विज्ञान और इंजीनियरी अनुसंधान बोर्ड अधिनियम, 2008 को निरस्त कर दिया।", "reason": "The Anusandhan National Research Foundation is expected to draw most of its projected funding for its first five years from non-government sources.", "reason_hi": "अनुसंधान नेशनल रिसर्च फ़ाउंडेशन से अपेक्षा है कि वह अपने पहले पाँच वर्षों के अनुमानित वित्त का अधिकांश भाग ग़ैर-सरकारी स्रोतों से जुटाए।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": true}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, but Statement-II does not explain Statement-I. The 2023 Act set up the Foundation to fund and steer research across the natural sciences, engineering, social sciences and humanities, and it subsumed the Science and Engineering Research Board (SERB), whose Act was repealed; its governing board is headed by the Prime Minister. Of the roughly ₹50,000 crore projected for its first five years, about ₹36,000 crore was expected from industry and other non-government sources. SERB was folded in so that one apex body would fund research, not because of where the money would come from.','दोनों कथन सही हैं, पर कथन-II कथन-I की व्याख्या नहीं करता। 2023 के अधिनियम ने प्राकृतिक विज्ञान, इंजीनियरी, सामाजिक विज्ञान और मानविकी में अनुसंधान को वित्त और दिशा देने के लिए फ़ाउंडेशन बनाया, और विज्ञान एवं इंजीनियरी अनुसंधान बोर्ड (SERB) को उसमें मिला दिया, जिसका अधिनियम निरस्त हुआ; इसके शासी बोर्ड के प्रमुख प्रधानमंत्री हैं। पहले पाँच वर्षों के लिए अनुमानित लगभग ₹50,000 करोड़ में से लगभग ₹36,000 करोड़ उद्योग और अन्य ग़ैर-सरकारी स्रोतों से आने की अपेक्षा थी। SERB को इसलिए मिलाया गया ताकि अनुसंधान को वित्त देने वाली एक शीर्ष संस्था हो, इसलिए नहीं कि पैसा कहाँ से आएगा।','statute-anrf-act-2023','original_pattern_matched','Anusandhan National Research Foundation Act, 2023; Department of Science and Technology.','draft'),
('upsc','Polity','Constitutional & Statutory Bodies','mcq','medium','With reference to the National Commission for Women, which one of the following statements is correct?','राष्ट्रीय महिला आयोग के संदर्भ में निम्नलिखित में से कौन-सा कथन सही है?','{}'::jsonb,'[{"id": "a", "body": "It is a constitutional body set up under Article 338 of the Constitution.", "body_hi": "यह संविधान के अनुच्छेद 338 के तहत स्थापित एक संवैधानिक निकाय है।", "isCorrect": false}, {"id": "b", "body": "Its chairperson is appointed by the President on the advice of the Chief Justice of India.", "body_hi": "इसके अध्यक्ष की नियुक्ति राष्ट्रपति भारत के मुख्य न्यायाधीश की सलाह पर करते हैं।", "isCorrect": false}, {"id": "c", "body": "It can itself impose punishment on persons found guilty of violating women''s rights.", "body_hi": "यह महिलाओं के अधिकारों का उल्लंघन करने के दोषी व्यक्तियों को स्वयं दंड दे सकता है।", "isCorrect": false}, {"id": "d", "body": "While investigating a complaint, it has the powers of a civil court trying a suit.", "body_hi": "किसी शिकायत की जाँच करते समय इसे वाद की सुनवाई करने वाले दीवानी न्यायालय की शक्तियाँ प्राप्त होती हैं।", "isCorrect": true}]'::jsonb,2,0.66,'The NCW is a statutory body set up in January 1992 under the National Commission for Women Act, 1990; it is not a constitutional body like the National Commission for Scheduled Castes (Article 338). The Union government nominates its chairperson, five members and a member-secretary. It reviews the legal safeguards for women, looks into complaints and can take suo motu notice; while investigating it has the powers of a civil court -- summoning witnesses, calling for documents and receiving evidence on affidavits. It recommends action to the authorities but cannot punish anyone itself.','राष्ट्रीय महिला आयोग राष्ट्रीय महिला आयोग अधिनियम, 1990 के तहत जनवरी 1992 में बना एक वैधानिक निकाय है; यह राष्ट्रीय अनुसूचित जाति आयोग (अनुच्छेद 338) की तरह संवैधानिक निकाय नहीं है। केंद्र सरकार इसके अध्यक्ष, पाँच सदस्यों और एक सदस्य-सचिव को मनोनीत करती है। यह महिलाओं के क़ानूनी सुरक्षा उपायों की समीक्षा करता है, शिकायतों की जाँच करता है और स्वतः संज्ञान ले सकता है; जाँच के समय इसे दीवानी न्यायालय की शक्तियाँ मिलती हैं, जैसे गवाहों को बुलाना, दस्तावेज़ मँगवाना और शपथपत्र पर साक्ष्य लेना। यह अधिकारियों से कार्रवाई की सिफ़ारिश करता है, पर स्वयं किसी को दंड नहीं दे सकता।','bodies-ncw-statutory-powers','original_pattern_matched','National Commission for Women Act, 1990; National Commission for Women.','draft')
